/** Ana malzemeye göre veto listesi — mutfak bilinmiyorsa Türkçeye düşer. */
export function uyumFor(cuisine: string, mainSlug: string): UyumEntry | undefined {
  return UYUM[cuisine]?.[mainSlug] ?? UYUM.tr?.[mainSlug];
}
